//! Conformance vectors for the L2 simulator (ADR 0030 section 4).
//!
//! Reads `schema/conformance/l2_sim.json`, generated by `scripts/gen_l2_vectors.py` from
//! hand-derived expectations (not recorded from `L2Sim`), and replays every scenario through
//! [`honba_sim::L2Sim`], asserting the drained fills / rejections and the final state. Each
//! scenario is replayed twice and must give identical output (determinism). The Python replay is
//! chunk E3-S1b-2. A drift test regenerates the file with `gen_l2_vectors.py --check`.

use std::path::PathBuf;
use std::process::Command;

use honba_engine::{AlgoError, ExecutionEngine};
use honba_entities::{Currency, Money};
use honba_messages::{
    AggressorSide, Exchange, InstrumentId, Order, OrderId, OrderSide, OrderType, QuoteTick,
    TimeInForce, TradeId, TradeTick, UnixNanos,
};
use honba_sim::{FillCostFn, L2Sim};
use serde_json::Value;

/// Vector chunks the Rust simulator implements.
const IMPLEMENTED_CHUNKS: &[u64] = &[1];

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn fixture() -> Value {
    let path = root().join("schema/conformance/l2_sim.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn iid(symbol: &str) -> InstrumentId {
    InstrumentId::new(symbol, Exchange::new("NSE"))
}

fn ts(v: &Value) -> UnixNanos {
    UnixNanos::from_u64(v.as_u64().unwrap())
}

/// JSON equality where `10` equals `10.0` (Python writes an int quantity as an int).
fn same(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x.as_f64() == y.as_f64(),
        (Value::Array(x), Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y).all(|(p, q)| same(p, q))
        }
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).is_some_and(|w| same(v, w)))
        }
        _ => a == b,
    }
}

fn side(s: &str) -> OrderSide {
    if s == "buy" {
        OrderSide::Buy
    } else {
        OrderSide::Sell
    }
}

fn side_str(s: OrderSide) -> &'static str {
    if s == OrderSide::Buy {
        "buy"
    } else {
        "sell"
    }
}

fn order(step: &Value) -> Order {
    let order_type = match step["type"].as_str().unwrap() {
        "market" => OrderType::Market,
        "limit" => OrderType::Limit,
        "stop_market" => OrderType::StopMarket,
        "stop_limit" => OrderType::StopLimit,
        "trailing_stop" => OrderType::TrailingStop,
        other => panic!("unknown order type {other}"),
    };
    let tif = match step["tif"].as_str().unwrap_or("day") {
        "day" => TimeInForce::Day,
        "gtc" => TimeInForce::Gtc,
        "ioc" => TimeInForce::Ioc,
        "fok" => TimeInForce::Fok,
        other => panic!("unknown tif {other}"),
    };
    let t = ts(&step["ts"]);
    let o = Order::new(
        OrderId::new(step["id"].as_str().unwrap()),
        iid(step["symbol"].as_str().unwrap()),
        side(step["side"].as_str().unwrap()),
        order_type,
        step["qty"].as_f64().unwrap(),
        step["price"].as_f64(),
        tif,
        t,
        t,
    );
    match step["trigger"].as_f64() {
        Some(trigger) => o.with_trigger_price(trigger),
        None => o,
    }
}

fn quote(step: &Value) -> QuoteTick {
    let t = ts(&step["ts"]);
    let f = |k: &str| step[k].as_f64().unwrap();
    QuoteTick::new(
        iid(step["symbol"].as_str().unwrap()),
        f("bid"),
        f("ask"),
        f("bid_size"),
        f("ask_size"),
        t,
        t,
    )
}

fn trade(step: &Value) -> TradeTick {
    let t = ts(&step["ts"]);
    let aggressor = match step["aggressor"].as_str().unwrap_or("buyer") {
        "buyer" => AggressorSide::Buyer,
        "seller" => AggressorSide::Seller,
        _ => AggressorSide::NoAggressor,
    };
    TradeTick::new(
        iid(step["symbol"].as_str().unwrap()),
        step["price"].as_f64().unwrap(),
        step["size"].as_f64().unwrap(),
        aggressor,
        TradeId::new(format!("T-{}", t.as_u64())),
        t,
        t,
    )
}

/// The vectors' test cost model: `flat + (notional * bps + 5000) / 10000` per side, in minor
/// units (the generator documents it).
fn cost_fn(spec: &Value) -> FillCostFn {
    let get = |k: &str| spec[k].as_i64().unwrap_or(0);
    let (flat_buy, flat_sell) = (get("flat_buy"), get("flat_sell"));
    let (bps_buy, bps_sell) = (get("bps_buy"), get("bps_sell"));
    Box::new(move |side, qty, price| {
        let notional = Money::mul_qty(qty, price, Currency::Inr)
            .map_err(|e| AlgoError::Component(e.to_string()))?
            .minor();
        let (flat, bps) = if side == OrderSide::Buy {
            (flat_buy, bps_buy)
        } else {
            (flat_sell, bps_sell)
        };
        Ok(Money::new(
            flat + (notional * bps + 5000).div_euclid(10_000),
            Currency::Inr,
        ))
    })
}

fn build(config: &Value) -> L2Sim {
    assert_eq!(config["currency"], "INR");
    let cash = Money::new(config["cash"].as_i64().unwrap(), Currency::Inr);
    let mut sim = L2Sim::new(cash)
        .unwrap()
        .with_long_only(config["long_only"].as_bool().unwrap());
    if config.get("costs").is_some() {
        sim = sim.with_costs(cost_fn(&config["costs"]));
    }
    for (symbol, lot) in config["lot_sizes"].as_object().unwrap() {
        sim.set_lot_size(&iid(symbol), lot.as_f64().unwrap())
            .unwrap();
    }
    sim
}

fn drain(sim: &mut L2Sim) -> Value {
    let fills: Vec<Value> = sim
        .drain_fills()
        .unwrap()
        .iter()
        .map(|f| {
            serde_json::json!([
                f.order_id().as_str(),
                f.instrument_id().symbol(),
                side_str(f.side()),
                f.quantity(),
                f.price(),
                f.ts_event().as_u64(),
                f.costs().minor(),
            ])
        })
        .collect();
    let rejections: Vec<Value> = sim
        .drain_rejections()
        .unwrap()
        .iter()
        .map(|r| {
            serde_json::json!([
                r.order_id.as_str(),
                r.instrument_id.symbol(),
                side_str(r.side),
                r.quantity,
                r.reason,
                r.ts.as_u64(),
            ])
        })
        .collect();
    serde_json::json!({"fills": fills, "rejections": rejections})
}

/// Replays one scenario; returns `{"drains": [...], "final": {...}}` in the fixture's shape.
fn replay(sc: &Value) -> Value {
    let name = sc["name"].as_str().unwrap();
    let mut sim = build(&sc["config"]);
    let mut drains: Vec<Value> = Vec::new();
    for step in sc["steps"].as_array().unwrap() {
        let result = match step["op"].as_str().unwrap() {
            "quote" => sim.on_quote(&quote(step)),
            "trade" => sim.on_trade(&trade(step)),
            "submit" => ExecutionEngine::submit(&mut sim, order(step)),
            "cancel" => {
                ExecutionEngine::cancel(&mut sim, step["id"].as_str().unwrap(), ts(&step["now"]))
            }
            "advance_ts" => sim.advance_to(ts(&step["ts"])),
            "session_close" => sim.on_session_close(ts(&step["ts"])),
            "set_position" => sim.set_position(
                &iid(step["symbol"].as_str().unwrap()),
                step["qty"].as_f64().unwrap(),
            ),
            "drain" => {
                drains.push(drain(&mut sim));
                Ok(())
            }
            other => panic!("{name}: unknown op {other}"),
        };
        let expect_error = step["error"].as_bool().unwrap_or(false);
        assert_eq!(
            result.is_err(),
            expect_error,
            "{name}: step {step} error mismatch: {result:?}"
        );
    }
    let mut positions = sim.positions();
    positions.sort_by(|a, b| a.0.cmp(&b.0));
    let positions: serde_json::Map<String, Value> = positions
        .iter()
        .map(|(id, q)| (id.symbol().to_string(), serde_json::json!(q)))
        .collect();
    serde_json::json!({
        "drains": drains,
        "final": {
            "cash": sim.cash().minor(),
            "positions": positions,
            "working": sim.working_orders(),
            "fees": sim.fees().minor(),
            "traded_notional": sim.traded_notional().minor(),
        },
    })
}

#[test]
fn l2_vectors_replay_byte_identically() {
    let doc = fixture();
    assert_eq!(doc["fixture_version"], 1);
    assert_eq!(doc["type"], "L2Sim");
    let mut replayed = 0;
    for sc in doc["scenarios"].as_array().unwrap() {
        if !IMPLEMENTED_CHUNKS.contains(&sc["chunk"].as_u64().unwrap()) {
            continue;
        }
        let name = sc["name"].as_str().unwrap();
        let got = replay(sc);
        assert!(
            same(&got["drains"], &sc["expect"]["drains"]),
            "{name}: drained fills and rejections\n got {}\nwant {}",
            got["drains"],
            sc["expect"]["drains"]
        );
        assert!(
            same(&got["final"], &sc["expect"]["final"]),
            "{name}: final state\n got {}\nwant {}",
            got["final"],
            sc["expect"]["final"]
        );
        // Determinism: a second run over the same steps gives the same output, bit for bit.
        assert_eq!(got, replay(sc), "{name}: replay is not deterministic");
        replayed += 1;
    }
    assert!(replayed > 0, "no scenario replayed");
}

#[test]
fn l2_vectors_cover_every_adr_0030_matching_row() {
    let doc = fixture();
    let names: Vec<&str> = doc["scenarios"]
        .as_array()
        .unwrap()
        .iter()
        .map(|s| s["name"].as_str().unwrap())
        .collect();
    for needle in [
        "market_fills",
        "partial_by_top_size",
        "marketable_limit",
        "trade_through",
        "stop_market",
        "stop_limit",
        "ioc",
        "fok",
        "day_orders_expire",
        "fifo",
        "cancel",
        "trailing_stop",
        "insufficient_funds",
        "no_position",
        "deterministic",
    ] {
        assert!(
            names.iter().any(|n| n.contains(needle)),
            "no scenario covers {needle}"
        );
    }
}

/// The committed file is exactly what `scripts/gen_l2_vectors.py` generates (the L1 vectors are
/// checked the same way by their Python test). Skipped, loudly, only when python3 is missing.
#[test]
fn committed_vectors_match_the_generator() {
    let status = Command::new("python3")
        .arg(root().join("scripts/gen_l2_vectors.py"))
        .arg("--check")
        .status();
    match status {
        Ok(s) => assert!(
            s.success(),
            "schema/conformance/l2_sim.json is stale: run python3 scripts/gen_l2_vectors.py"
        ),
        Err(e) => eprintln!("skipping generator drift check: python3 unavailable ({e})"),
    }
}
